def required(record, key):
    return record[key]

def optional(record, key, fallback):
    return record.get(key, fallback)

def discard(record, key):
    return record.pop(key, None)

def delete_note(record):
    if "note" in record:
        del record["note"]

print(optional({}, "score", 0))
